function @@proc@@(p_val in varchar2) return number is
  l_cnt number;
begin
  execute immediate -- @expect
    q'[select count(*) from @@tab@@ where @@col@@ = ']' /* open quote */
    || p_val
    || ''''
    into l_cnt;
  return l_cnt;
end @@proc@@;

procedure @@proc@@(p_tab in varchar2) is
  l_sql varchar2(400);
  l_rows number;
  procedure note(p_t in varchar2) is
  begin
    dbms_output.put_line(p_t);
  end note;
begin
  begin
    declare
      l_part varchar2(100) := 'where @@col@@ is null';
    begin
      l_sql := 'delete from ' || p_tab || ' ' || l_part;
    end;
  end;
  note('built');
  execute immediate l_sql; -- @expect
  l_rows := sql%rowcount;
  note(l_rows);
end @@proc@@;

function @@proc@@(p_min in number, p_desc in boolean) return sys_refcursor is
  l_cur sys_refcursor;
  l_sql varchar2(300);
begin
  $IF $$use_archive $THEN
  l_sql := 'select id from @@tab@@_arch where qty > ' || to_char(p_min);
  $ELSE
  l_sql := 'select id from @@tab@@ where qty > ' || to_char(p_min);
  $END
  if p_desc then
    l_sql := l_sql || ' order by id desc';
  end if;
  open l_cur for l_sql; -- @expect
  return l_cur;
end @@proc@@;

procedure @@proc@@(p_proc in varchar2, p_n in number) is
  l_i number := 0;
begin
  <<run>>
  loop
    l_i := l_i + 1;
    exit run when l_i > p_n;
	execute immediate 'begin ' || p_proc -- @expect
	  || '(:1); end;'
	  using l_i;
  end loop run;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_done boolean := false;
begin
  begin
    @@proc2@@(p_id);
  exception
    when dup_val_on_index then
      l_done := true;
    when others then
      raise;
  end;
  if not l_done then
    execute immediate 'delete from "Order Line" where id = ' || p_id; -- @expect
  end if;
end @@proc@@;

