function @@proc@@(p_val in varchar2) return varchar2 is
  l_v varchar2(100);
begin
  -- l_sql := 'select ' || p_val || ' from dual';
  execute immediate q'[select 'x' || :1 from dual]' into l_v using p_val;
  dbms_output.put_line(l_v);
  return l_v;
end @@proc@@;

procedure @@proc@@(p_owner in varchar2, p_obj in varchar2, p_id in number) is
begin
	execute immediate 'delete from ' /* schema first */
	  || dbms_assert.schema_name(p_owner) || '.'
	  || dbms_assert.sql_object_name(p_obj) -- validated names only
	  || ' where id = :1'
	  using p_id;
  dbms_output.put_line(sql%rowcount);
end @@proc@@;

function @@proc@@(p_val in varchar2) return number is
  l_sql varchar2(200);
  l_other varchar2(200);
  l_cnt number;
begin
  l_other := 'select ' || p_val || ' from dual';
  l_sql := 'select count(*) from @@tab@@';
  dbms_output.put_line(length(l_other));
  -- execute immediate l_other;
  execute immediate l_sql into l_cnt;
  return l_cnt;
end @@proc@@;

procedure @@proc@@(p_prefix in varchar2, p_id in number) is
  l_rows number;
begin
  execute immediate
    'update @@tab@@ set @@col@@ = :1 where id = :2'
    using p_prefix || '-' || to_char(p_id), p_id;
  l_rows := sql%rowcount;
  dbms_output.put_line(l_rows);
end @@proc@@;

function @@proc@@(p_min in number) return sys_refcursor is
  l_cur sys_refcursor;
begin
  <<outer>>
  begin
    /* not built as 'where qty > ' || p_min */
    open l_cur for
      select ol.id, ol.qty
        from "Order Line" ol
       where ol.qty > p_min;
  end outer;
  return l_cur;
end @@proc@@;
